  frame->header.configGeneration = readU32Le(payload);
  frame->header.frameId = readU32Le(payload + 4);
  frame->header.captureTimeUs = readU64Le(payload + 8);
  frame->header.fpsQ8_8 = readU16Le(payload + 16);
